const body = $json.body || $json;

function boolish(v) {
  return (
    v === true ||
    v === 1 ||
    String(v || '').trim().toLowerCase() === 'true' ||
    String(v || '').trim().toLowerCase() === 'yes' ||
    String(v || '').trim().toLowerCase() === '1'
  );
}

return [{
  json: {
    mode: String(body.mode || 'all').toLowerCase(),
    date: String(body.date || ''),
    timezone: String(body.timezone || 'America/Denver'),
    include_review: boolish(body.include_review)
  }
}];

const req = $('Code - Parse List Request').first().json;
const rows = Array.isArray($json.records) ? $json.records : [];

function zonedParts(v, tz) {
  if (!v) return null;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;

  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).formatToParts(d);

  return Object.fromEntries(parts.map(p => [p.type, p.value]));
}

function dateKey(v, tz) {
  const m = zonedParts(v, tz);
  if (!m) return '';
  return `${m.year}-${m.month}-${m.day}`;
}

function localDateTime(v, tz) {
  if (!v) return '';
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  }).format(d);
}

function parseItems(s) {
  try {
    const a = typeof s === 'string' ? JSON.parse(s) : [];
    return Array.isArray(a) ? a : [];
  } catch (e) {
    return [];
  }
}

function itemSummary(items) {
  return items
    .map(i => `${i.name || i.nameTranslated?.en || '(unknown)'} x${Number(i.quantity || 0) || 0}`)
    .join(', ');
}

/*
  IMPORTANT:
  Treat requested date as a plain calendar date, not a moment in time.
  Do not convert it through Date()/timezone math.
*/
function normalizeReqDate(v) {
  const s = String(v || '').trim();
  if (!s) return '';

  const m = s.match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : '';
}

const mode = String(req.mode || 'all');
const timezone = req.timezone || 'America/Denver';
const reqDateRaw = req.date || '';
const reqDate = normalizeReqDate(reqDateRaw);

const out = [];
const debug = [];

for (const rec of rows) {
  const f = rec.fields || {};
  const items = parseItems(f.items_json);

  const requiredCount = items.reduce(
    (n, i) => n + (Number(i.quantity || 0) || 0),
    0
  );

  const linkedProducts = Array.isArray(f.products) ? f.products : [];
  const linkedCount = linkedProducts.length;

  const paymentMethod = String(f.payment_method || '');
  const market = String(paymentMethod || '').startsWith('Sell on the Go');  

  const reconciliationStatus = String(f.clover_reconciliation_status || '').toLowerCase();
  const paymentStatus = String(f.payment_status || '').toUpperCase();

  const includeReview =
    req.include_review === true ||
    String(req.include_review || '').toLowerCase() === 'true';

  const accounted = reconciliationStatus === 'accounted';

  const reviewable =
    market &&
    ['pending', 'needs_review'].includes(reconciliationStatus);

  const marketCash = market && paymentMethod === 'Sell on the Go - Cash';

  const ready = marketCash
    ? (paymentStatus === 'PAID' || accounted)
    : market
      ? (reconciliationStatus === 'reconciled' || accounted)
      : paymentStatus === 'PAID';  

  const rowDate = dateKey(f.order_date, timezone);

  let excludedBy = null;

  if (mode === 'market' && !market) {
    excludedBy = 'mode_market';
  } else if (mode === 'web' && market) {
    excludedBy = 'mode_web';
  } else if (!ready && !(includeReview && reviewable)) {
    excludedBy = 'not_ready';
  } else if (reqDate && rowDate !== reqDate) {
    excludedBy = 'date';
  } else if (linkedCount >= requiredCount) {
    excludedBy = 'already_fulfilled';
  }

  debug.push({
    id: rec.id,
    order_code: f.order_code || null,
    payment_method: paymentMethod,
    market,
    payment_status: f.payment_status || null,
    clover_reconciliation_status: f.clover_reconciliation_status || null,
    order_date_raw: f.order_date || null,
    row_date: rowDate,
    req_date_raw: reqDateRaw || null,
    req_date: reqDate || null,
    linked_count: linkedCount,
    required_count: requiredCount,
    excluded_by: excludedBy,
    reconciliation_status: reconciliationStatus,
    include_review: includeReview,
    ready,
    reviewable,
    accounted
  });

  if (excludedBy) continue;

  out.push({
    airtable_record_id: rec.id,
    order_ref: String(f.order_code || f.ecwid_order_id || f.order_number || ''),
    order_number: f.order_number || null,
    order_date: f.order_date || null,
    order_date_local: localDateTime(f.order_date, timezone),
    order_date_local_date: rowDate,
    customer_name: f.customer_name || '',
    payment_method: paymentMethod,
    payment_status: f.payment_status || '',
    clover_reconciliation_status: f.clover_reconciliation_status || '',
    payment_state: market
      ? (reconciliationStatus || 'pending')
      : (f.payment_status || ''),
    needs_reconciliation_review: market && !ready,
    reviewable,
    accounted,
    mode: market ? 'market' : 'web',
    linked_count: linkedCount,
    required_count: requiredCount,
    product_names: itemSummary(items) || '(none)',
    products_report: f.products_report || '',
    product_ids_report: f.product_ids_report || '',
    items,
    reconciliation_notes: f.reconciliation_notes || ''
  });
}

out.sort((a, b) => String(a.order_date || '').localeCompare(String(b.order_date || '')));

return [{
  json: {
    ok: true,
    req: {
      ...req,
      date_raw: reqDateRaw,
      date: reqDate,
      timezone
    },
    orders: out,
    count: out.length,
    debug
  }
}];

const f=$json.fields||{}; function parseItems(s){ try{ const a=typeof s==='string'?JSON.parse(s):[]; return Array.isArray(a)?a:[];}catch(e){return [];} }
const items=parseItems(f.items_json).map((i,idx)=>({line_index:idx+1,name:i.name||i.nameTranslated?.en||'(unknown)',sku:i.sku||'',productId:i.productId||null,quantity:Number(i.quantity||0)||0}));
const linked=Array.isArray(f.products)?f.products:[];
const summary=`Ecwid ${String(f.order_code||f.ecwid_order_id||f.order_number||'')} | ${f.customer_name||''} | linked ${linked.length} of ${items.reduce((n,i)=>n+i.quantity,0)} required`;
return [{json:{ok:true, airtable_record_id:$json.id, order_ref:String(f.order_code||f.ecwid_order_id||f.order_number||''), summary, items, linked_products:linked, products_report:f.products_report||'', product_ids_report:f.product_ids_report||'', raw_fields:f}}];

const body = $json.body || $json;
const query = String(body.query || '').trim().toLowerCase();

return [{
  json: {
    query,
    allow_search: query.length >= 2
  }
}];

const req = $('Code - Parse Product Search').first().json;
const q = String(req.query || '').trim().toLowerCase();
const companyName = $env['BUSINESS_NAME'] || null;

const locResp = $('HTTP - List Locations Airtable').first().json || {};
const locRecords = Array.isArray(locResp.records) ? locResp.records : [];
const locMap = new Map(
  locRecords.map(r => [r.id, String(r.fields?.name || '')])
);

const inputs = $input.all();
const rows = inputs.flatMap(item => {
  const records = item.json?.records;
  return Array.isArray(records) ? records : [];
});

const products = [];

for (const rec of rows) {
  const f = rec.fields || {};

  if (companyName && String(f.label_company_prod || '') !== companyName) continue;

  const hay = [
    f.product_id,
    f.name_mat,
    f.unit_size,
    f.item_category_mat,
    f.notes
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  if (q && !hay.includes(q)) continue;

  const locIds = Array.isArray(f.storage_location) ? f.storage_location : [];
  const locNames = locIds.map(id => locMap.get(id) || id);

  products.push({
    airtable_record_id: rec.id,
    product_id: f.product_id || '',
    name_mat: f.name_mat || '',
    unit_size: f.unit_size || '',
    item_category_mat: f.item_category_mat || '',
    storage_location: locIds,
    storage_location_name: locNames.join(', '),
    notes: f.notes || ''
  });
}

return [{
  json: {
    ok: true,
    page_count: inputs.length,
    raw_record_count: rows.length,
    products: products.slice(0, 100),
    count: products.length
  }
}];

const req = $('Code - Parse Product Search').first().json;
const companyName = $env['BUSINESS_NAME'] || null;
const query = String(req.query || '').trim().toLowerCase();

function formulaEscape(s) {
  return String(s || '')
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"');
}

const clauses = [];

if (companyName) {
  clauses.push(`{label_company_prod}="${formulaEscape(companyName)}"`);
}

// Exclude by linked-record display names, not record IDs
for (const locName of ['Shipped', 'Consumed', 'Compost', 'Expired']) {
  clauses.push(`NOT(FIND("${formulaEscape(locName.toLowerCase())}", LOWER(ARRAYJOIN({storage_location}&""))))`);
}

if (req.allow_search && query) {
  clauses.push(`OR(
    FIND("${formulaEscape(query)}", LOWER({product_id}&"")),
    FIND("${formulaEscape(query)}", LOWER({name_mat}&"")),
    FIND("${formulaEscape(query)}", LOWER({unit_size}&"")),
    FIND("${formulaEscape(query)}", LOWER({item_category_mat}&"")),
    FIND("${formulaEscape(query)}", LOWER({notes}&""))
  )`);
}

const filter_formula =
  clauses.length === 1 ? clauses[0] : `AND(${clauses.join(',')})`;

return [{
  json: {
    query,
    allow_search: !!req.allow_search,
    company_name: companyName,
    filter_formula,
    offset: ''
  }
}];

const data = $getWorkflowStaticData('global');

if (!Array.isArray(data.fulfillmentProductSearchRecords)) {
  data.fulfillmentProductSearchRecords = [];
}

const pageRecords = Array.isArray($json.records) ? $json.records : [];
data.fulfillmentProductSearchRecords.push(...pageRecords);

return [{
  json: {
    offset: $json.offset || '',
    page_count: pageRecords.length,
    accumulated_count: data.fulfillmentProductSearchRecords.length
  }
}];

const data = $getWorkflowStaticData('global');
const allRecords = Array.isArray(data.fulfillmentProductSearchRecords)
  ? data.fulfillmentProductSearchRecords
  : [];

const out = [{
  json: {
    records: allRecords,
    count: allRecords.length
  }
}];

data.fulfillmentProductSearchRecords = [];

return out;

const body = $json.body || $json;
const id = String(body.airtable_order_record_id || body.airtable_record_id || '').trim();
if (!id) throw new Error('Missing airtable_order_record_id');
const operator = String(body.operator || 'system').trim() || 'system';
const note = String(body.note || 'Cash/manual payment accounted for; no Clover card reconciliation required.').trim();
const nowIso = new Date().toISOString();
return [{
  json: {
    airtable_order_record_id: id,
    result: {
      ok: true,
      airtable_order_record_id: id,
      reconciliation_status: 'accounted',
      message: 'Order marked accounted for without Clover card reconciliation.'
    },
    fields: {
      clover_reconciliation_status: 'accounted',
      clover_payment_id: null,
      clover_payment_amount: null,
      clover_payment_time: null,
      clover_match_confidence: null,
      reconciled_at: null,
      reconciliation_notes: [
        note,
        `Accounted at: ${nowIso}`,
        `Operator: ${operator}`
      ].filter(Boolean).join(' | ')
    }
  }
}];

const body = $json.body || $json;
const id = String(body.airtable_order_record_id || body.airtable_record_id || '').trim();
const paymentId = String(body.clover_payment_id || '').trim();
if (!id) throw new Error('Missing airtable_order_record_id');
if (!paymentId) throw new Error('Missing clover_payment_id');

const amountRaw = body.clover_payment_amount;
const amount = amountRaw === undefined || amountRaw === null || amountRaw === ''
  ? null
  : Number(amountRaw);
if (amount !== null && !Number.isFinite(amount)) throw new Error('Invalid clover_payment_amount');

function isoOrNull(v) {
  if (!v) return null;
  const d = new Date(v);
  if (!Number.isFinite(d.getTime())) throw new Error('Invalid clover_payment_time');
  return d.toISOString();
}

const paymentTime = isoOrNull(body.clover_payment_time);
const cloverOrderId = String(body.clover_order_id || '').trim();
const tenderId = String(body.clover_tender_id || '').trim();
const operator = String(body.operator || 'system').trim() || 'system';
const note = String(body.note || 'Manually matched Clover payment in Appsmith.').trim();
const nowIso = new Date().toISOString();

return [{
  json: {
    airtable_order_record_id: id,
    result: {
      ok: true,
      airtable_order_record_id: id,
      reconciliation_status: 'reconciled',
      clover_payment_id: paymentId,
      message: 'Order manually reconciled to Clover payment.'
    },
    fields: {
      clover_reconciliation_status: 'reconciled',
      clover_payment_id: paymentId,
      clover_payment_amount: amount,
      clover_payment_time: paymentTime,
      clover_match_confidence: 0.5,
      reconciled_at: nowIso,
      reconciliation_notes: [
        note,
        'Manually reconciled by operator.',
        cloverOrderId ? `Clover order id: ${cloverOrderId}` : null,
        tenderId ? `Tender id: ${tenderId}` : null,
        `Operator: ${operator}`
      ].filter(Boolean).join(' | ')
    }
  }
}];
